def mark_approved_documents(apps, schema_editor):
    """Documents of already-approved drivers were approved as a whole before per-document review."""
    Document = apps.get_model("verification", "VerificationDocument")
    for doc in Document.objects.filter(verification__status="approved").select_related("verification"):
        doc.status = "approved"
        doc.reviewed_at = doc.verification.reviewed_at
        doc.reviewed_by_id = doc.verification.reviewed_by_id
        doc.save(update_fields=["status", "reviewed_at", "reviewed_by"])


